import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  user: vi.fn(),
  candidates: vi.fn(),
  markUnavailable: vi.fn(),
  complete: vi.fn(),
  del: vi.fn(),
  rm: vi.fn(),
}));
vi.mock("@vercel/blob", () => ({ del: mocks.del }));
vi.mock("node:fs/promises", () => ({ rm: mocks.rm }));
vi.mock("@/lib/db", () => ({
  db: {
    $transaction: async (work: (tx: unknown) => Promise<unknown>) =>
      work({
        $queryRaw: vi.fn(),
        user: { findUnique: mocks.user },
        attachment: {
          findMany: mocks.candidates,
          updateMany: mocks.markUnavailable,
        },
      }),
    attachment: { updateMany: mocks.complete },
  },
}));
import { cleanupAttachments } from "@/lib/storage";

const userId = "f5a05555-5732-4463-b29e-d4cdfef33354";
const file = {
  id: "f5a05555-5732-4463-b29e-d4cdfef33355",
  userId,
  storagePath: `resumes/${userId}/f5a05555-5732-4463-b29e-d4cdfef33355.pdf`,
};

describe("attachment cleanup progress", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "FAKE-TEST-TOKEN");
    mocks.user.mockResolvedValue({ currentAttachmentId: "current-resume" });
    mocks.candidates.mockResolvedValue([file]);
  });
  afterEach(() => vi.unstubAllEnvs());

  it("retains historical metadata and skips completed deletions on the next run", async () => {
    let completed = false;
    mocks.candidates.mockImplementation(async ({ where }) =>
      where.storageDeletedAt === null && completed ? [] : [file],
    );
    mocks.complete.mockImplementation(async () => {
      completed = true;
      return { count: 1 };
    });
    await cleanupAttachments(userId);
    await cleanupAttachments(userId);
    expect(mocks.del).toHaveBeenCalledOnce();
    expect(mocks.del).toHaveBeenCalledWith(
      [file.storagePath],
      expect.objectContaining({ abortSignal: expect.any(AbortSignal) }),
    );
    expect(mocks.complete).toHaveBeenCalledWith({
      where: { userId, id: { in: [file.id] }, storageDeletedAt: null },
      data: { storageDeletedAt: expect.any(Date) },
    });
  });

  it("leaves failed physical deletions pending and retries them", async () => {
    mocks.del.mockRejectedValueOnce(new Error("provider unavailable"));
    await cleanupAttachments(userId);
    expect(mocks.complete).not.toHaveBeenCalled();
    await cleanupAttachments(userId);
    expect(mocks.del).toHaveBeenCalledTimes(2);
    expect(mocks.complete).toHaveBeenCalledOnce();
    expect(mocks.markUnavailable).toHaveBeenCalledWith({
      where: { userId, id: { in: [file.id] }, deletedAt: null },
      data: { deletedAt: expect.any(Date) },
    });
  });

  it("bounds the batch and preserves current, queued, and uncertain attachment references", async () => {
    await cleanupAttachments(userId);
    expect(mocks.candidates).toHaveBeenCalledWith({
      where: {
        userId,
        storageDeletedAt: null,
        id: { not: "current-resume" },
        campaigns: {
          none: {
            userId,
            sends: {
              some: {
                OR: [
                  { status: "QUEUED" },
                  { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
                ],
              },
            },
          },
        },
      },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      take: 10,
    });
  });

  it("does not touch a path outside the account namespace", async () => {
    mocks.candidates.mockResolvedValue([
      { ...file, storagePath: "resumes/other-account/owned.pdf" },
    ]);
    await cleanupAttachments(userId);
    expect(mocks.del).not.toHaveBeenCalled();
    expect(mocks.rm).not.toHaveBeenCalled();
    expect(mocks.complete).not.toHaveBeenCalled();
  });

  it("treats an absent local file as deleted, so retries can finish", async () => {
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "");
    vi.stubEnv("NODE_ENV", "test");
    await cleanupAttachments(userId);
    expect(mocks.rm).toHaveBeenCalledWith(
      expect.stringContaining(file.storagePath),
      { force: true },
    );
    expect(mocks.complete).toHaveBeenCalledOnce();
  });

  it("does not mark production deletions completed without configured storage", async () => {
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "");
    vi.stubEnv("NODE_ENV", "production");
    await cleanupAttachments(userId);
    expect(mocks.del).not.toHaveBeenCalled();
    expect(mocks.rm).not.toHaveBeenCalled();
    expect(mocks.complete).not.toHaveBeenCalled();
  });
});
